sp_widget.client_script:
api.controller = function($scope, $element) {
  var c = this;

  function getOptInt(name, fallback) {
    var v = parseInt(($scope.options && $scope.options[name]), 10);
    return isNaN(v) ? fallback : v;
  }

  function getViewport() {
    // Find within this widget instance
    return $element[0].querySelector('#libCarouselViewport');
  }

  $scope.scroll = function(dir) {
    var vp = getViewport();
    if (!vp) return;

    var visible = getOptInt('carousel_visible', 4);
    var step = getOptInt('carousel_step', 2);

    // Estimate card width from first card in viewport
    var card = vp.querySelector('.lib-card--carousel');
    var cardW = card ? (card.getBoundingClientRect().width || 220) : 220;

    // Add gap (12px matches grid gap)
    var delta = (cardW + 12) * step;

    vp.scrollBy({ left: dir * delta, behavior: 'smooth' });
  };
};

sp_widget.css:
/* Wrapper spacing */
.lib-widget {
  margin-top: 16px;
  margin-bottom: 16px;
}

.lib-widget--dense {
  margin-top: 8px;
  margin-bottom: 8px;
}

.lib-widget-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}

.lib-widget-title {
  font-weight: 700;
  font-size: 16px;
  color: rgba(0,0,0,0.9);
}

/* Carousel */
.lib-carousel {
  position: relative;
}

.lib-carousel-viewport {
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: 4px 34px; /* room for arrows */
}

.lib-carousel-track {
  display: flex;
  gap: 12px;
}

.lib-card--carousel {
  flex: 0 0 180px; /* base card width in carousel */
}

.lib-carousel-btn {
  position: absolute;
  top: 40%;
  transform: translateY(-50%);
  width: 28px;
  height: 48px;
  border-radius: 10px;
  border: 1px solid rgba(0,0,0,0.12);
  background: rgba(255,255,255,0.92);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  z-index: 2;
}

.lib-carousel-btn--left { left: 0; }
.lib-carousel-btn--right { right: 0; }

sp_widget.script:
(function () {
  data.error = "";
  data.items = [];
  data.series = { sys_id: "", display: "" };

  var o = options || {};

  function asBool(v) { return v === true || v === "true"; }

  var bookTable = (o.book_table || "").trim();
  var sysIdParam = (o.sys_id_param || "sys_id").trim();
  var urlSysId = ("" + ($sp.getParameter(sysIdParam) || "")).trim();

  var mode = (o.mode || "encoded_query").trim();

  var titleField = (o.title_field || "title").trim();
  var subtitleField = (o.subtitle_field || "").trim();
  var imageField = (o.image_field || "").trim();

  var limit = parseInt(o.limit, 10);
  if (isNaN(limit) || limit <= 0) limit = 50;
  if (limit > 200) limit = 200;

  data.ui = {
    widget_title: (o.widget_title || "").trim(),
    show_title: asBool(o.show_title),
    layout: (o.layout || "grid").trim(),
    dense: asBool(o.dense),

    link_page: (o.link_page || "library_book").trim(),
    link_param: (o.link_param || "sys_id").trim(),

    empty_text: (o.empty_text || "No books found.").trim(),

    show_sequence_badge: asBool(o.show_sequence_badge),
    show_series_link: asBool(o.show_series_link),
    series_link_page: (o.series_link_page || "library_series").trim()
  };

  function makeItem(gr, seq) {
    var item = {
      sys_id: gr.getUniqueValue(),
      title: "",
      subtitle: "",
      image_url: "",
      sequence: seq || ""
    };

    if (titleField && gr.isValidField(titleField)) item.title = gr.getDisplayValue(titleField) || "";
    else item.title = gr.getDisplayValue() || "";

    if (subtitleField) {
      try { item.subtitle = gr.getDisplayValue(subtitleField) || ""; } catch (e) { item.subtitle = ""; }
    }

    if (imageField && gr.isValidField(imageField)) {
      item.image_url = gr.getDisplayValue(imageField) || "";
    }

    return item;
  }

  // ------- MODE: encoded_query (like card_grid) -------
  if (mode === "encoded_query") {
    var q = (o.query || "").trim();
    var ob = (o.order_by || "").trim();
    var desc = asBool(o.order_desc);

    var gr = new GlideRecord(bookTable);
    if (!gr.isValid()) { data.error = "Invalid book table: " + bookTable; return; }

    if (q) gr.addEncodedQuery(q);
    if (ob && gr.isValidField(ob)) {
      if (desc) gr.orderByDesc(ob);
      else gr.orderBy(ob);
    }
    gr.setLimit(limit);
    gr.query();

    while (gr.next()) data.items.push(makeItem(gr, ""));

    return;
  }

  // ------- MODE: series_from_series_page / series_from_book_page -------
  var m2mTable = (o.m2m_table_series || "").trim();
  var m2mSeriesField = (o.m2m_series_field || "series").trim();
  var m2mBookField = (o.m2m_book_field || "book").trim();
  var m2mSeqField = (o.m2m_sequence_field || "sequence_number").trim();

  if (!urlSysId) { data.error = "Missing sys_id in URL"; return; }
  if (!m2mTable) { data.error = "Missing m2m_table_series option"; return; }

  // resolve series sys_id
  var seriesSysId = "";

  if (mode === "series_from_series_page") {
    seriesSysId = urlSysId;
    data.series.sys_id = seriesSysId;

  } else if (mode === "series_from_book_page") {
    var bookSeriesField = (o.book_series_field || "series").trim();
    var b = new GlideRecord(bookTable);
    if (!b.isValid()) { data.error = "Invalid book table: " + bookTable; return; }
    if (!b.get(urlSysId)) { data.error = "Book not found"; return; }
    if (!b.isValidField(bookSeriesField)) { data.error = "Invalid book_series_field: " + bookSeriesField; return; }

    seriesSysId = ("" + b.getValue(bookSeriesField)).trim();
    data.series.sys_id = seriesSysId;
    data.series.display = b.getDisplayValue(bookSeriesField) || "";

    if (!seriesSysId) return; // no series: empty state, not error

  } else {
    data.error = "Invalid mode: " + mode;
    return;
  }

  // query m2m
  var m2m = new GlideRecord(m2mTable);
  if (!m2m.isValid()) { data.error = "Invalid M2M table: " + m2mTable; return; }
  if (!m2m.isValidField(m2mSeriesField) || !m2m.isValidField(m2mBookField)) {
    data.error = "Invalid M2M field config";
    return;
  }

  m2m.addQuery(m2mSeriesField, seriesSysId);
  if (m2mSeqField && m2m.isValidField(m2mSeqField)) m2m.orderBy(m2mSeqField);
  else m2m.orderBy("sys_created_on");
  m2m.setLimit(limit);
  m2m.query();

  var bookIds = [];
  var seqByBook = {};
  var order = [];

  while (m2m.next()) {
    var bId = ("" + m2m.getValue(m2mBookField)).trim();
    if (!bId) continue;

    var seq = "";
    if (m2mSeqField && m2m.isValidField(m2mSeqField)) seq = ("" + m2m.getValue(m2mSeqField)).trim();

    if (!seqByBook[bId]) {
      seqByBook[bId] = seq;
      bookIds.push(bId);
      order.push(bId);
    }
  }

  if (bookIds.length === 0) return;

  var books = new GlideRecord(bookTable);
  if (!books.isValid()) { data.error = "Invalid book table: " + bookTable; return; }
  books.addQuery("sys_id", "IN", bookIds.join(","));
  books.query();

  var map = {};
  while (books.next()) {
    var id = books.getUniqueValue();
    map[id] = makeItem(books, seqByBook[id] || "");
  }

  for (var i = 0; i < order.length; i++) {
    if (map[order[i]]) data.items.push(map[order[i]]);
  }
})();
